import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    """Raised when rate limit is exceeded after retries."""
    pass


class ServerError(Exception):
    """Raised when server errors persist after retries."""
    pass


class ClientError(Exception):
    """Raised on client errors (4xx except 429)."""
    pass


class ConnectionError(Exception):
    """Raised when network errors persist after retries."""
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        """
        Make a GET request to base_url + path.
        Handles retries for 429, 5xx, and network errors.
        """
        url = self.base_url + path

        # For 429: retry up to 3 times with exponential backoff (0.5, 1, 2)
        # For 5xx: retry once after 1s
        # For network errors: retry once after 1s
        # For 4xx (except 429): raise immediately

        # We need to handle different error types with different retry strategies.
        # Let's structure this carefully.

        # Strategy:
        # - Try the request
        # - If 429, retry up to 3 times with backoff 0.5, 1, 2
        # - If 5xx, retry once after 1s
        # - If network error, retry once after 1s
        # - If 4xx (not 429), raise immediately

        # We'll use a loop for 429 retries, and separate handling for others.

        # First, let's handle 429 retries
        num_429_retries = 3
        backoff_times = [0.5, 1, 2]

        for attempt in range(num_429_retries + 1):  # 0 to 3, so 4 attempts total (initial + 3 retries)
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if attempt < num_429_retries:
                        time.sleep(backoff_times[attempt])
                        continue
                    else:
                        raise RateLimitError(f"Rate limit exceeded after {num_429_retries} retries")
                elif 500 <= e.code < 600:
                    # Server error: retry once after 1s
                    # We need to retry once, so we do one retry
                    time.sleep(1)
                    try:
                        req = urllib.request.Request(url)
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as e2:
                        if 500 <= e2.code < 600:
                            raise ServerError(f"Server error {e2.code} after retry")
                        elif e2.code == 429:
                            # This shouldn't happen in this branch but handle it
                            raise RateLimitError(f"Rate limit exceeded")
                        elif 400 <= e2.code < 500:
                            raise ClientError(f"Client error {e2.code}")
                        else:
                            raise ServerError(f"Server error {e2.code} after retry")
                    except urllib.error.URLError as e2:
                        # Network error on retry
                        raise ConnectionError(f"Connection error after retry")
                elif 400 <= e.code < 500:
                    raise ClientError(f"Client error {e.code}")
                else:
                    # Other HTTP errors
                    raise ServerError(f"HTTP error {e.code}")
            except urllib.error.URLError as e:
                # Network error: retry once after 1s
                time.sleep(1)
                try:
                    req = urllib.request.Request(url)
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.HTTPError as e2:
                    if e2.code == 429:
                        raise RateLimitError(f"Rate limit exceeded")
                    elif 500 <= e2.code < 600:
                        raise ServerError(f"Server error {e2.code} after retry")
                    elif 400 <= e2.code < 500:
                        raise ClientError(f"Client error {e2.code}")
                    else:
                        raise ServerError(f"HTTP error {e2.code} after retry")
                except urllib.error.URLError as e2:
                    raise ConnectionError(f"Connection error after retry")
